 @page "/enroll"
 @using UniversityCourseCatalog.Models
 @using UniversityCourseCatalog.Services
 @inject CatalogService Catalog

 <PageTitle>Enrollment Request</PageTitle>

 <h1>Enrollment Request</h1>
 <p>Complete the form below to submit your enrollment request.</p>

 @if (submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Request Submitted!</h4>
         <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@GetCourseName(Model.CourseId)</strong> has been received.</p>
         <hr />
         <p class="mb-0">You will receive a confirmation via your university email.</p>
     </div>
     <a href="enroll" class="btn btn-primary">Submit Another Request</a>
 }
 else
 {
     <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="row g-3" style="max-width: 600px;">
         <AntiforgeryToken />
         <DataAnnotationsValidator />
         <ValidationSummary class="text-danger" />

         <div class="col-12">
             <label for="studentName" class="form-label">Full Name</label>
             <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
             <ValidationMessage For="() => Model.StudentName" class="text-danger" />
         </div>

         <div class="col-12">
             <label for="studentId" class="form-label">Student ID</label>
             <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g., STU12345" />
             <ValidationMessage For="() => Model.StudentId" class="text-danger" />
         </div>

         <div class="col-12">
             <label for="courseId" class="form-label">Course</label>
             <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                 <option value="0">— Select a course —</option>
                 @foreach (var course in allCourses)
                 {
                     <option value="@course.Id">@course.CourseCode — @course.Title</option>
                 }
             </InputSelect>
             <ValidationMessage For="() => Model.CourseId" class="text-danger" />
         </div>

         <div class="col-12">
             <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
         </div>
     </EditForm>
 }

 @code {
     [SupplyParameterFromForm]
     private EnrollmentRequest? Model { get; set; }

     protected override void OnParametersSet()
     {
         Model ??= new();
     }

     [SupplyParameterFromQuery]
     public int? CourseId { get; set; }

     private IReadOnlyList<Course> allCourses = [];
     private bool submitted;

     protected override void OnInitialized()
     {
         allCourses = Catalog.GetAllCourses();

         if (CourseId.HasValue && Model.CourseId == 0)
         {
             Model.CourseId = CourseId.Value;
         }
     }

     private void HandleSubmit()
     {
         submitted = true;
     }

     private string GetCourseName(int courseId)
     {
         var course = Catalog.GetCourse(courseId);
         return course is not null ? $"{course.CourseCode} — {course.Title}" : "Unknown";
     }
 }

